<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('guru');$pdo=db();$students=$pdo->query("SELECT id,nama_lengkap,nis,kelas,level FROM students WHERE status='aktif' ORDER BY kelas,nama_lengkap")->fetchAll();$studentId=(string)($_GET['student_id']??($students[0]['id']??''));$selected=null;foreach($students as $row)if($row['id']===$studentId)$selected=$row;$type=(string)($_GET['type']??'daily');if(!in_array($type,['daily','level','munaqosyah'],true))$type='daily';$counts=['daily'=>0,'level'=>0,'munaqosyah'=>0];if($studentId){foreach(['daily'=>'daily_student_reports','level'=>'level_promotion_exams','munaqosyah'=>'munaqosyah_exams'] as $key=>$table){$stmt=$pdo->prepare("SELECT COUNT(*) FROM $table WHERE student_id=?");$stmt->execute([$studentId]);$counts[$key]=(int)$stmt->fetchColumn();}}$pageTitle='3 Rapor Otomatis';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Template Rapor Resmi</p><h1 class="page-title">3 Rapor Otomatis</h1><p class="page-description">Nilai otomatis dari Presensi & Harian, Ujian Kenaikan Level, dan Form Munaqosyah.</p></div></div><section class="card"><form method="get" class="filter-row"><div class="field" style="min-width:min(560px,100%)"><label>Pilih Siswa</label><select class="select" name="student_id" onchange="this.form.submit()"><?php foreach($students as $student):?><option value="<?= e($student['id']) ?>" <?= $student['id']===$studentId?'selected':'' ?>><?= e($student['nama_lengkap'].' · '.$student['nis'].' · Kelas '.$student['kelas']) ?></option><?php endforeach;?></select></div><input type="hidden" name="type" value="<?= e($type) ?>"></form></section><section class="grid grid-3" style="margin-top:20px"><?php foreach(['daily'=>['Rapor Hafalan Harian','Nilai dari Presensi & Laporan Harian','▤'],'level'=>['Rapor Hafalan Level','Nilai dari Ujian Kenaikan Level','♢'],'munaqosyah'=>['Rapor Munaqosyah','Nilai dari Form Munaqosyah','♙']] as $key=>$meta):?><a class="stat <?= $type===$key?'green':'' ?>" href="<?= url('guru/reports.php?student_id='.e($studentId).'&type='.$key) ?>"><small><?= e($meta[1]) ?></small><strong style="font-size:21px"><?= $meta[2] ?> <?= e($meta[0]) ?></strong><span><?= $counts[$key] ?> data tersambung</span></a><?php endforeach;?></section><?php if($selected):?><section class="card" style="margin-top:20px"><div class="filter-row"><div><p class="eyebrow">Preview Rapor</p><h2 style="font-size:28px;margin:3px 0"><?= e($selected['nama_lengkap']) ?></h2></div><div class="actions"><a class="btn btn-soft" href="<?= url('api/reports/export.php?student_id='.$studentId) ?>">⇩ Download Excel</a><a class="btn btn-primary" target="_blank" href="<?= url('report.php?student_id='.$studentId.'&type='.$type) ?>">▧ Cetak / Simpan PDF</a></div></div><iframe title="Preview rapor" src="<?= url('report.php?student_id='.$studentId.'&type='.$type.'&embed=1') ?>" style="width:100%;height:840px;border:1px solid var(--line);border-radius:14px;background:#eee"></iframe></section><?php else:?><section class="card"><div class="empty"><strong>Belum ada siswa</strong>Tambahkan siswa sebelum membuat rapor.</div></section><?php endif;?><?php require ROOT_PATH.'/includes/footer.php';?>

